changeSet.sql:
ALTER TABLE catalogue_state ADD COLUMN order_version BIGINT NOT NULL DEFAULT 0;
CREATE TABLE catalogue_book_order (
  kind VARCHAR(7) NOT NULL CHECK(kind IN ('catalog','library')),
  book_key VARCHAR(36) NOT NULL,
  sort_order BIGINT NOT NULL CHECK(sort_order >= 0),
  PRIMARY KEY(kind,book_key)
);
